lab.solution:
from math import comb

def pair_count(n):
    if type(n) is not int or n < 0:
        raise ValueError('n must be a nonnegative integer')
    return n * (n - 1) // 2

for n in range(9):
    assert pair_count(n) == comb(n, 2)
for invalid in (-1, 2.5, True):
    try:
        pair_count(invalid)
    except ValueError:
        pass
    else:
        raise AssertionError('invalid size accepted')
print('pair-count tests checked')
